def find_smallest_n(received_string, substring):
    from itertools import permutations

    def is_valid_n(n):
        return str(n) == str(n)[0].lstrip('0') if n != 0 else True

    def all_possible_ns(substring, received_string):
        len_substring = len(substring)
        for perm in permutations(received_string, len_substring):
            possible_n = int(''.join(perm))
            if str(possible_n).startswith(substring):
                yield possible_n

